use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-reverse-leaf176";
fn read(n:&str)->Value{serde_json::from_slice(&fs::read(format!("{R}/{n}")).unwrap()).unwrap()}fn hash(p:&str)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn save(n:&str,v:&Value){fs::write(format!("{R}/{n}"),serde_json::to_vec_pretty(v).unwrap()).unwrap();}
fn main(){assert!(!Path::new(&format!("{R}/candidate-plan.json")).exists());let failure=read("native/failure.json");assert_eq!(failure["completed"],json!(["core-off","libraries-off","freeze-off","core-on","libraries-on"]));assert_eq!(read("native/freeze-on/exit.json")["success"],false);assert!(!Path::new(&format!("{R}/artifacts-on.json")).exists());let mut source=fs::read_to_string(format!("{R}/native.rs")).unwrap();assert_eq!(source.matches("native/libraries-{label}").count(),1);source=source.replace("native/libraries-{label}","candidate-native/libraries-{label}");assert_eq!(source.matches("target-{label}/release/.fingerprint").count(),1);source=source.replace("target-{label}/release/.fingerprint","target-candidate/release/.fingerprint");fs::write(format!("{R}/candidate-native.rs"),source).unwrap();let old=read("build-plan.json");let mut steps=old["steps"].as_array().unwrap()[3..].to_vec();assert_eq!(steps.len(),3);let base=fs::read_to_string(format!("{R}/native-flags.txt")).unwrap();for step in&mut steps{assert_eq!(step["environment"]["RUSTFLAGS"],format!("{base} --cfg zopro_g2_late_y"));step["environment"]["RUSTFLAGS"]=json!(format!("{base} --cfg zopro_g2_reverse_leaf"));step["environment"]["CARGO_TARGET_DIR"]=json!(format!("{R}/target-candidate"));if step["name"]=="freeze-on"{step["argv"][0]=json!(format!("{R}/candidate-native-helper"));}}let mut pins:BTreeMap<String,String>=serde_json::from_value(read("build-pins.json")).unwrap();for(p,h)in&pins{assert_eq!(hash(p),*h);}for n in["repair-candidate.rs","candidate-native.rs","candidate-native-helper","candidate-repair.md","native/failure.json","native/freeze-on/command.json","native/freeze-on/exit.json","native/freeze-on/stderr.log"]{let p=format!("{R}/{n}");pins.insert(p.clone(),hash(&p));}save("candidate-pins.json",&json!(pins));save("candidate-plan.json",&json!({"version":1,"source_pins":format!("{R}/candidate-pins.json"),"steps":steps}));println!("Prepared3correctcandidate steps in target-candidate; original5success+1freeze failure retained; OFF unchanged; candidate tests have NOT yet passed");}
